// 期望入参: company, contact_name, title, email, industry, employees, source, note
const results = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const emp = Number(b.employees) || 0;
  const title = String(b.title || '').toLowerCase();
  let score = 0;
  // 决策人职位
  if (/(ceo|founder|owner|总经理|董事|创始|合伙|vp|总监|director|head)/.test(title)) score += 35;
  else if (/(manager|经理|采购|buyer|主管)/.test(title)) score += 20;
  // 公司规模
  if (emp >= 50 && emp <= 1000) score += 30;
  else if (emp > 1000) score += 20;
  else if (emp >= 10) score += 10;
  // 有企业邮箱
  const email = String(b.email || '').toLowerCase();
  if (email && !/@(gmail|qq|163|126|outlook|hotmail|yahoo)\./.test(email)) score += 20;
  // 有备注/明确需求
  if (String(b.note || '').length > 10) score += 15;
  const grade = score >= 70 ? 'A' : score >= 45 ? 'B' : 'C';
  results.push({ json: {
    company: b.company || '',
    contact_name: b.contact_name || '',
    title: b.title || '',
    email,
    industry: b.industry || '',
    employees: emp,
    source: b.source || 'webhook',
    note: b.note || '',
    score, grade,
    status: '新线索',
    created_at: new Date().toISOString(),
  }});
}
return results;

